/// <summary>
/// PricingAttribute of table <c>InventDim</c> field InventVersionId.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesLine, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeInventDimInventVersionId extends GUPPricingAttributeInventDim implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventVersionId);
}

public Set getAllowedValues()
{
    var       ret = new Set(Types::String);
    InventDim inventDim;

    while select inventDim
        group by InventVersionId
    {
        if (! ret.in(inventDim.InventVersionId))
        {
            ret.add(inventDim.InventVersionId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventVersionId));
    qbr.value(queryValue(_value));
}
